+  it("returns null when the query is not a subsequence", () => {
+    expect(fuzzyMatch("hello", "xyz")).toBeNull();
+    expect(fuzzyMatch("abc", "cba")).toBeNull();
+    expect(fuzzyMatch("ab", "abc")).toBeNull();
